from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[2]/'assets/phase-2';m=json.loads((R/'models/manifest.json').read_text());audio=json.loads((R/'audio/manifest.json').read_text());ui=json.loads((R/'ui/manifest.json').read_text());h=html.escape
modelcards=''
for a in m['assets']:
 id=a['id'];modelcards+=f'''<article class="model-card"><a href="#inspect" onclick="selectModel('{id}','intact')"><img loading="lazy" src="models/previews/{id}-intact.png" alt="{h(a['zh'])}完整模型"></a><div class="card-content"><h3>{h(a['zh'])}</h3><p>{a['fragmentCount']} 个实体碎片 · 最长边 {a['longestDimensionM']*100:.0f} 厘米</p><div class="buttons"><button onclick="selectModel('{id}','intact')">查看完整模型</button><button onclick="selectModel('{id}','fragments')">查看碎片</button></div><p class="downloads"><a href="models/{id}/intact.glb" download>完整 GLB</a><a href="models/{id}/fragments.glb" download>碎片 GLB</a><a href="models/{id}/collision-hulls.glb" download>组合碰撞体</a><a href="models/{id}/metadata.json" download>尺寸与质量</a></p></div></article>'''
audiocards=''
for g,title in [('glass','玻璃'),('ceramic','陶瓷'),('plastic','电子塑料'),('custom','自定义通用')]:
 audiocards+=f'<article><h3>{title}</h3><p>串联试听：投掷 → 碎裂 → 碎片落地</p><audio controls preload="none" src="audio/{g}-preview.wav"></audio><details><summary>展开 9 个独立样本</summary>'
 for event,label in [('throw','投掷'),('shatter','碰撞碎裂'),('fragment-land','碎片落地')]:
  for i in range(1,4):audiocards+=f'<label class="audio-row">{label} · {i}<audio controls preload="none" src="audio/materials/{g}/{event}-{i:02}.wav"></audio></label>'
 audiocards+='</details></article>'
uiaudio=''
for name,title in [('confirm','确认'),('cancel','取消'),('pick','拿取'),('refresh-start','刷新开始'),('refresh-complete','刷新完成'),('failure','失败提示'),('reset-complete','重置完成')]:uiaudio+=f'<label class="audio-row">{title}<audio controls preload="none" src="audio/ui/{name}.wav"></audio></label>'
uicards=''
for name,title in [('safety','安全提示'),('controller','手柄检测提示'),('reset','重置确认'),('counter-zero','初始计数栏'),('counter-active','使用后显示对应物品计数'),('object-panel','物品选择面板')]:
 uicards+=f'<article><h3>{title}</h3><div class="pair">'+''.join(f'<figure><figcaption>{lab}</figcaption><img loading="lazy" src="ui/{name}-{lang}@2x.png" alt="{lab}{title}"></figure>'for lang,lab in [('zh','中文'),('en','英文')])+'</div></article>'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>碎境 · 第二阶段素材验收</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#efefea;color:#26382c;font:16px/1.6 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif}main{max-width:1450px;margin:auto;padding:60px 40px}h1{font-size:48px;line-height:1.2;font-weight:500;margin:12px 0 22px}h2{font-size:30px;font-weight:500;margin:0 0 12px}h3{font-size:20px;font-weight:500;margin:0 0 10px}p{margin:8px 0;color:#5c6b60}small{font-size:12px;letter-spacing:2px;color:#6b7b6b}a{color:inherit;text-underline-offset:4px}nav{display:flex;gap:14px;flex-wrap:wrap;margin:26px 0}nav a,.buttons button{border:1px solid #bac5b9;border-radius:20px;padding:9px 15px;text-decoration:none;background:transparent;color:inherit;font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #75a685;outline-offset:3px}section{margin-top:65px}.stats{display:flex;gap:40px;margin:36px 0}.stats b{display:block;font-size:34px;font-weight:500}.stats span{color:#657467;font-size:14px}.notice{border-left:3px solid #a2bca2;padding:10px 20px;max-width:1040px;font-size:14px}#inspect{scroll-margin-top:20px}.viewer{display:grid;grid-template-columns:1fr 280px;gap:24px;align-items:start}.viewer iframe{width:100%;height:600px;border:0;border-radius:20px;background:#c7cac4}.viewer aside{padding:24px 0}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.buttons button{font-size:13px;padding:7px 12px}.range{width:100%;accent-color:#527e60;margin-top:20px}.models{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:20px}.model-card{background:#fff7;border-radius:20px;overflow:hidden}.model-card img{width:100%;display:block;aspect-ratio:1;object-fit:cover}.card-content{padding:16px}.card-content h3{font-size:18px}.card-content p{font-size:12px}.downloads{display:flex;gap:8px;flex-wrap:wrap}.sounds{display:grid;grid-template-columns:repeat(2,1fr);gap:30px}.sounds>article{background:#fff8;padding:24px;border-radius:20px}audio{width:100%;height:38px}.audio-row{display:block;font-size:13px;margin:15px 0;color:#526653}.audio-row audio{display:block;margin-top:6px}details{margin-top:20px}summary{cursor:pointer;font-size:14px}.ui-list>article{margin:32px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pair img{width:100%;max-height:400px;object-fit:contain;display:block;background:#c7cac4;border-radius:18px;padding:20px}figure{margin:0}figcaption{font-size:13px;color:#627468;margin-bottom:8px}.icon-preview{display:flex;gap:28px;align-items:center}.icon-preview img{width:160px;border-radius:35px}.download-line{display:flex;gap:18px;flex-wrap:wrap;font-size:14px}.bottom{border-top:1px solid #bcc7b9;padding-top:30px;margin-top:60px}#selected-meta{font-size:14px}.hint{font-size:13px}footer{font-size:14px;color:#627468}@media(max-width:1000px){.models{grid-template-columns:repeat(3,1fr)}.viewer{grid-template-columns:1fr}.viewer iframe{height:500px}}@media(max-width:650px){main{padding:32px 20px}.models,.sounds,.pair{grid-template-columns:1fr 1fr}.pair{grid-template-columns:1fr}.stats{gap:20px}h1{font-size:36px}.viewer iframe{height:400px}}
</style><main><header><small>第二阶段 / 素材制作 / 待用户验收</small><h1>每一件物品，都可以拆开看。</h1><p>完整模型、对应实体碎片、UI 素材与音效集中评审。这里加载的是实际导出的 GLB 和 WAV 文件。</p><div class="stats"><div><b>15</b><span>内置物品</span></div><div><b>389</b><span>封闭实体碎片</span></div><div><b>43</b><span>独立音频样本</span></div></div><nav><a href="#inspect">三维查看器</a><a href="#models">全部物品</a><a href="#ui">界面与应用图标</a><a href="#audio">音效试听</a><a href="README.md">交付说明</a><a href="review/asset-validation.json">结构检查报告</a></nav><p class="notice">官方 Spatial Editor 托管流程未能产出模型，本版采用原创本地参数化建模与实体切分。玻璃/陶瓷破碎与落地音已改为CC0实录剪辑，其他音效保留原程序合成。此页用于素材验收，未执行 PICO 手势、空间平面或物理运行；碎片分离演示也不是物理模拟。</p></header><section id="inspect"><h2 id="selected-title">玻璃杯</h2><div class="viewer"><iframe id="model-view" title="可旋转的三维资产预览" src="viewer.html?id=glass-cup"></iframe><aside><p id="selected-meta"></p><div class="buttons"><button onclick="setMode('intact')">完整模型</button><button onclick="setMode('fragments')">实体碎片</button><button onclick="setMode('collision-hulls')">碰撞体</button></div><label class="hint">碎片展开程度<input class="range" type="range" min="0" max="1" step=".01" value=".38" oninput="document.getElementById('model-view').contentWindow.assetViewer?.explode(this.value)"></label><p class="hint">拖动旋转，滚轮缩放。碰撞体为组合凸体近似，具体误差和数量见各物品 metadata.json；头显性能尚未验证。</p><p class="hint">若透明玻璃在浅底上不易辨识，可旋转观察轮廓、切换实体碎片或碰撞体。</p></aside></div></section><section id="models"><h2>三类材质，十五种日用品</h2><p>顺序依次为玻璃、陶瓷、电子塑料，每类五件。点击物品可在上方旋转查看。</p><p class="download-line"><a href="models/previews/catalog-atlas.png">完整模型总览</a><a href="models/previews/fracture-atlas.png">全部碎片总览</a></p><div class="models">'''+modelcards+'''</div></section><section id="ui"><h2>界面与应用图标</h2><p>中英文分别导出，动态文字目录独立保留。初始计数栏只显示总数；物品首次成功碎裂后再显示其计数。</p><div class="icon-preview"><img src="ui/launcher-master.png" alt="应用图标"><div><h3>应用图标</h3><p>无文字裂隙标记；前景、背景、单色层与多尺寸 PNG 已分开导出。</p><div class="download-line"><a href="ui/launcher-foreground.svg">前景 SVG</a><a href="ui/launcher-background.svg">背景 SVG</a><a href="ui/launcher-monochrome.svg">单色 SVG</a><a href="ui/manifest.json">全部 UI 清单</a></div></div></div><div class="ui-list">'''+uicards+'''</div></section><section id="audio"><h2>先听材质，再听反馈</h2><p><a href="audio-review.html">重点试听：玻璃与陶瓷修订第2版（含新旧对比）</a></p><p>48kHz 单声道 PCM16 WAV。每种材质有投掷、碎裂、碎片落地三类事件，每类三个变体；实际音色等待你试听确认。</p><div class="sounds">'''+audiocards+'''</div><h3 style="margin-top:34px">界面交互音</h3><div class="sounds">'''+uiaudio+'''</div></section><footer class="bottom">本阶段交付的是素材与制作源，不包含 APK。请确认模型造型、碎片效果、UI 与声音，确认全部素材后才进入第三阶段功能开发。</footer></main><script>
const assets=__ASSETS__;let currentId='glass-cup';function selectModel(id,type){currentId=id;const a=assets.find(x=>x.id===id);document.getElementById('selected-title').textContent=a.zh;document.getElementById('selected-meta').textContent=`${a.fragmentCount} 个实体碎片 · ${a.massKg} 千克 · 最长边 ${(a.longestDimensionM*100).toFixed(0)} 厘米`;const frame=document.getElementById('model-view');frame.src='viewer.html?id='+id+'&type='+type;document.querySelector('.range').value='.38'}function setMode(type){selectModel(currentId,type)}selectModel('glass-cup','intact');
</script></html>'''
page=page.replace('>389<','>'+str(m['totalFragments'])+'<')
page=page.replace('__ASSETS__',json.dumps([{k:a[k] for k in ['id','zh','fragmentCount','massKg','longestDimensionM']} for a in m['assets']],ensure_ascii=False))
# Cache-bust the revised audio, so an already-open browser cannot replay its cached v1.
for group in ['glass','ceramic']:
 for event in ['shatter','fragment-land']:
  for v in range(1,4):page=page.replace(f'audio/materials/{group}/{event}-{v:02}.wav',f'audio/materials/{group}/{event}-{v:02}.wav?rev=2')
 page=page.replace(f'audio/{group}-preview.wav',f'audio/{group}-preview.wav?rev=2')
(R/'index.html').write_text(page)
# A screenshot of a code-native layout produces an unlabelled texture atlas from actual model previews.
atlas='<!doctype html><html><style>body{margin:0}#atlas{display:grid;grid-template-columns:repeat(5,400px);width:2000px;gap:0}img{width:400px;height:400px;display:block}</style><div id="atlas">'+''.join(f'<img src="{a["id"]}-intact.png">'for a in m['assets'])+'</div></html>'
(R/'models/previews/atlas.html').write_text(atlas)
print('Asset gallery and actual-model atlas layout written')
